    def rfmodule_setup(self, **kwargs):
        config_device = kwargs['config_device']
        rfmod_inst_id = kwargs.get("rfmod_inst_id", '1')
        rfmodip_param_path = kwargs.get("rf_ip_distname",
                                        "/MRBTS-1/RAT-1/BTS_L-1/EQM_L-1/RMOD_L-{}:ipAddress".format(rfmod_inst_id))
        fhnet_login_only = kwargs.pop('fhnet_login_only', False)
        alias = kwargs.pop('alias', 'default')
        timeout = kwargs.pop('timeout', 10)

        rfmod_config_params = get_config_variable([config_device])
        bts_config_name = rfmod_config_params.get('bts_config_name', 'bts')

        host_details = self.remote_conn.get_host_details(bts_config_name)

        fhnet_login_timeout, fhnet_prompt, lxc_command, rfmod_login_timeout, rfmod_prompt, rfmodule_password, \
        rfmodule_user = self._get_rfmodule_config_params(rfmod_config_params)

        logger.info("Host Details are  {0}".format(host_details))
        self.controller.create_session_with_host(host_details, alias, timeout)

        self._login_to_fhnet(fhnet_prompt, fhnet_login_timeout, lxc_command, alias)

        # RF module login
        if not fhnet_login_only:
            ip_range = kwargs.get("iprange")
            rfmodule_ip = self._get_rf_module_ip_from_admin(rfmodip_param_path)
            self._check_if_rfmod_ip_in_range(rfmodule_ip, ip_range)  # Check if given rf module ip is in range
            if not rfmodule_ip:
                raise RFModuleLoginFailedException(
                    "Could not fetch RF Module ip from {}".format(rfmodip_param_path))
            logger.info("\t\t" + "====" * 4 + "RF Module IP: " + rfmodule_ip + "====" * 4)
            self._login_to_rfmodule(rfmodule_ip, rfmodule_user, rfmodule_password, rfmod_prompt, rfmod_login_timeout,
                                    alias)
            logger.info("============ login to rf module successful =============")

    def send_cmd_recv_output(self, cmd, timeout, prompt='$', alias="default", return_err=False):
        if return_err:
            output, err = self.controller.execute_command_on_shell(command=cmd, alias=alias, exit_prompt=prompt,
                                                                   timeout=timeout, return_rc=return_err)
            return output, err
        else:
            return self.controller.execute_command_on_shell(command=cmd, alias=alias, exit_prompt=prompt,
                                                            timeout=timeout, return_rc=return_err)

    def rfmodule_teardown(self, **kwargs):
        alias = kwargs.get("alias", "default")
        self.controller.close_session_with_host(alias=alias)

    def _get_rf_module_ip_from_admin(self, distname):
        admin_alias = _setup_oam_ops()
        return Parameters().get_parameter(param_path=distname, str_format=True, alias=admin_alias)

    def _convert_ipv4(self, ip):
        return tuple(int(n) for n in ip.split('.'))

    def _check_ipv4_in(self, addr, start, end):
        logger.info(type(start))
        return self._convert_ipv4(start) < self._convert_ipv4(addr) < self._convert_ipv4(end)

