    def _get_rfmodule_config_params(self, rfmod_config_params):
        rfmodule_user = rfmod_config_params['user']
        rfmodule_password = rfmod_config_params['password']
        lxc_command = rfmod_config_params['lxc_command']
        fhnet_prompt = rfmod_config_params['fhnet_prompt']
        rfmod_prompt = rfmod_config_params['rfmod_prompt']
        fhnet_login_timeout = 5
        rfmod_login_timeout = 5
        return fhnet_login_timeout, fhnet_prompt, lxc_command, rfmod_login_timeout, rfmod_prompt, rfmodule_password, \
               rfmodule_user

    def _get_bts_config_params(self, bts_config_name):
        bts_config_params = get_config_variable([bts_config_name])
        bts_ip = bts_config_params['ip']
        bts_user = bts_config_params['user']
        bts_password = bts_config_params['password']
        return bts_ip, bts_password, bts_user

    def _login_to_fhnet(self, fhnet_prompt, fhnet_login_timeout, lxc_command, alias):
        logger.info("\t" + "====" * 4 + "Login to FHNet" + "====" * 4)
        output = self.controller.execute_command_on_shell(command=lxc_command, alias=alias,
                                                          timeout=fhnet_login_timeout, exit_prompt=fhnet_prompt)
        if not bool(re.search(fhnet_prompt, output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
            raise FHNetLoginFailedException('FHNet prompt: {} not found'.format(fhnet_prompt))
        logger.info("\t\t" + "====" * 4 + "Success" + "====" * 4)

    def _login_to_rfmodule(self, rfmodule_ip, rfmodule_user, rfmodule_password, rfmod_prompt, rfmod_login_timeout,
                           alias):
        logger.info("\t" + "====" * 4 + "Login to RFModule" + "====" * 4)
        password_attempt = 1
        command = 'ssh {}@{}'.format(rfmodule_user, rfmodule_ip)
        output = self.controller.execute_command_on_shell(command=command, alias=alias, timeout=rfmod_login_timeout,
                                                          exit_prompt=rfmod_prompt)
        if bool(re.search(rfmod_prompt, output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
            return

        while bool(re.search('password', output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
            password_attempt += 1
            logger.debug('password attempt {} '.format(password_attempt))
            output = self.controller.execute_command_on_shell(command=rfmodule_password, alias=alias,
                                                              timeout=rfmod_login_timeout, exit_prompt=rfmod_prompt)
            if bool(re.search(rfmod_prompt, output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
                return
        else:
            if bool(re.search('Permission denied', output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
                raise RFModuleLoginFailedException('Invalid Password: {}'.format(rfmodule_password))
            elif bool(re.search(rfmod_prompt, output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
                if bool(re.search(rfmod_prompt, output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
                    return
        raise RFModuleLoginFailedException()

    def _check_if_rfmod_ip_in_range(self, rfmodule_ip, ip_range):
        if ip_range:
            logger.info('checking if ip {} in range'.format(rfmodule_ip))
            ip_range = ip_range.split("-")
            logger.info(ip_range)
            ip_range = (ip_range[0], ip_range[1])
            if not self._check_ipv4_in(rfmodule_ip, ip_range[0], ip_range[1]):
                raise Exception("Rf module ip not in given range {}".format(ip_range))
